import pathlib,json,hashlib,importlib.util,collections,numpy as np,math,datetime
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
SRC=R/'y06_r3_bear_retest_research_v2.py'
sp=importlib.util.spec_from_file_location('r3',SRC);r3=importlib.util.module_from_spec(sp);sp.loader.exec_module(r3)
bt=r3.bt;H=bt.H;M=bt.M
P=R/'Y06_R9_FACTOR_DECOMPOSITION_PROTOCOL_20261127.json';O=R/'Y06_R9_FACTOR_DECOMPOSITION_RESULTS_20261127.json'
assert not P.exists() and not O.exists()
p={'status':'RESEARCH_ONLY_EXPLORATORY_ALREADY_INSPECTED','source_sha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'snapshot':'Every UTC 0/6/12/18, >=8 QA eligible assets, preceding 168 completed H1 returns. OLS beta of alt on BTC, clipped [0,3], residual log returns alt-beta*BTC (no intercept removal), standardized by trailing residual hourly std times sqrt horizon. Score uses only confirmed bars.','regimes':'BEAR BTC trailing24 and72h returns negative and >=60% of QA peers trailing24h down; BULL symmetric; otherwise MIXED.','arms':{'BEAR_RESID_MOM':'BEAR, SHORT weakest normalized residual24h, score <=-0.5','BEAR_RESID_REV':'BEAR, SHORT strongest normalized residual24h, score >=0.5','BEAR_RAW_MOM':'BEAR, SHORT weakest raw24h, return negative','BEAR_DIVERGENCE':'BEAR, SHORT strongest residual6h minus residual72h, residual72h negative, score difference>=0.5','BULL_RESID_MOM':'BULL, LONG strongest residual24h >=0.5','BULL_RESID_REV':'BULL, LONG weakest residual24h <=-0.5','BOTH_MOM':'BEAR_RESID_MOM + BULL_RESID_MOM','BOTH_REV':'BEAR_RESID_REV + BULL_RESID_REV','MIXED_RESID_REV':'MIXED, compare absolute top/bottom residual24h, take opposite direction of larger extreme >=1.5'},'exit':'12/24/48h fixed exits, hard STOP8 symmetric, adverse gap, actual M5 open, 0.30 gross per position, original 2-slot wallet 12h cooldown, 10/30bps. Candidate ranking independent of future path availability. Only priced results; unresolved count.','decomposition':'At each snapshot and horizon measure market return beta component, residual log return, extreme quintile (2 or more), market regime and signed absolute price return. Diagnostic no STOP for horizon returns. Compare strongest/weakest residual cohorts same time.','controls':'32 seeded same-snapshot alternative-symbol controls on every arm with >=2 profitable periods or BOTH_MOM/BOTH_REV at 24h; same direction and same quality cohort, >=2 available alternatives, same wallet. Historical periods already inspected; thresholds frozen before results. No funding; no production.'}
P.write_text(json.dumps(p,indent=2),encoding='utf8')
btc,_=bt.data('BTC','1h'); bm,_=bt.data('BTC','5m');hs={};ms={};qa={}
for sym in bt.SYMS[1:]:
 h,_=bt.data(sym,'1h');m,_=bt.data(sym,'5m');hs[sym]=h;ms[sym]=m;qa[sym]=r3.prepare_qa(h,m)[0];print('LOAD',sym,flush=True)
def perof(t):return next((k for k,(a,b) in bt.PERIODS.items() if a<=t<b),None)
def endof(per):return bt.PERIODS[per][1] if per!='FORWARD_INSPECTED' else bt.T('2026-11-26T00:00:00Z')
def trade(x,side,hr):
 m=ms[x['symbol']];k=(x['entryTs']-bt.MS)//M;j=k+hr*12
 if k<0 or j>=len(m) or not np.isfinite(m[k:j+1,:4]).all():return None
 ep=float(m[k,0]);stop=ep*(1-side*.08);hit=np.flatnonzero(m[k:j,2]<=stop) if side==1 else np.flatnonzero(m[k:j,1]>=stop)
 et=bt.MS+j*M;xp=float(m[j,0]);reason='TIME'+str(hr)
 if len(hit):
  q=k+int(hit[0]);et=bt.MS+(q+1)*M;xp=float(min(m[q,0],stop) if side==1 else max(m[q,0],stop));reason='HARD_STOP8'
 if et>=endof(x['period']):return None
 return {**x,'exitTs':et,'entry':ep,'exitPrice':xp,'direction':'LONG' if side==1 else 'SHORT','rawReturn':side*(xp/ep-1),'exitReason':reason}
def compact(w):return {k:v for k,v in w.items() if k!='accepted'}
snaps={};signals={k:[] for k in p['arms']};diag=collections.defaultdict(list)
for i in range(220,len(btc)):
 t=bt.HS+i*H;per=perof(t)
 if not per or t%(6*H) or not np.isfinite(btc[i-169:i,3]).all():continue
 b=np.diff(np.log(btc[i-169:i,3]));bv=float(np.var(b))
 if bv<=1e-12:continue
 peers=[]
 for sym,h in hs.items():
  if not qa[sym][i] or not np.isfinite(h[i-169:i,3]).all():continue
  a=np.diff(np.log(h[i-169:i,3]));beta=float(np.clip(np.mean((a-a.mean())*(b-b.mean()))/bv,0,3));res=a-beta*b;sd=float(np.std(res))
  if sd<=1e-9:continue
  peers.append(dict(symbol=sym,entryTs=t,period=per,beta=beta,raw24=float(a[-24:].sum()),z6=float(res[-6:].sum()/sd/np.sqrt(6)),z24=float(res[-24:].sum()/sd/np.sqrt(24)),z72=float(res[-72:].sum()/sd/np.sqrt(72))))
 if len(peers)<8:continue
 breadth=float(np.mean([x['raw24']<0 for x in peers]));b24=b[-24:].sum();b72=b[-72:].sum()
 regime='BEAR' if b24<0 and b72<0 and breadth>=.6 else 'BULL' if b24>0 and b72>0 and breadth<=.4 else 'MIXED'
 for x in peers:x['regime']=regime
 snaps[t]=peers
 order=sorted(peers,key=lambda x:(x['z24'],x['symbol']));q=max(2,len(peers)//5)
 for hr in (3,6,12,24,48):
  k=(t-bt.MS)//M;j=k+hr*12
  if k<0 or j>=len(bm) or t+hr*H>=endof(per) or not np.isfinite(bm[[k,j],0]).all():continue
  br=float(np.log(bm[j,0]/bm[k,0]));g={'WEAK':order[:q],'STRONG':order[-q:],'ALL':order}
  for label,group in g.items():
   ar=[];beta_part=[];rr=[]
   for x in group:
    m=ms[x['symbol']]
    if j>=len(m) or not np.isfinite(m[[k,j],0]).all():continue
    a=float(np.log(m[j,0]/m[k,0]));ar.append(a);beta_part.append(x['beta']*br);rr.append(a-x['beta']*br)
   if len(ar)>=2:diag[(per,regime,hr,label)].append([np.mean(ar),np.mean(beta_part),np.mean(rr)])
 def add(name,x,side):signals[name].append((x,side))
 low,high=order[0],order[-1]
 if regime=='BEAR':
  if low['z24']<=-.5:add('BEAR_RESID_MOM',low,-1);add('BOTH_MOM',low,-1)
  if high['z24']>=.5:add('BEAR_RESID_REV',high,-1);add('BOTH_REV',high,-1)
  v=min(peers,key=lambda x:(x['raw24'],x['symbol']))
  if v['raw24']<0:add('BEAR_RAW_MOM',v,-1)
  div=[x for x in peers if x['z72']<0 and x['z6']-x['z72']>=.5]
  if div:add('BEAR_DIVERGENCE',max(div,key=lambda x:(x['z6']-x['z72'],x['symbol'])),-1)
 elif regime=='BULL':
  if high['z24']>=.5:add('BULL_RESID_MOM',high,1);add('BOTH_MOM',high,1)
  if low['z24']<=-.5:add('BULL_RESID_REV',low,1);add('BOTH_REV',low,1)
 else:
  v=max((low,high),key=lambda x:abs(x['z24']))
  if abs(v['z24'])>=1.5:add('MIXED_RESID_REV',v,1 if v['z24']<0 else -1)
D={}
for (per,regime,hr,g),a in diag.items():
 a=np.array(a);D.setdefault(per,{}).setdefault(regime,{}).setdefault(str(hr),{})[g]={'snapshots':len(a),'raw_log_pct':float(100*a[:,0].mean()),'beta_log_pct':float(100*a[:,1].mean()),'residual_log_pct':float(100*a[:,2].mean())}
for per,rs in D.items():
 for regime,hh in rs.items():
  if '24' in hh:print('DECOMP24',per,regime,json.dumps(hh['24']),flush=True)
out={};tapes={}
for arm,items in signals.items():
 for hr in (12,24,48):
  key=arm+'/'+str(hr);out[key]={};tapes[key]={}
  for per in bt.PERIODS:
   xx=[(x,d) for x,d in items if x['period']==per and x['entryTs']+hr*H<endof(per)]
   ts=[z for x,d in xx if (z:=trade(x,d,hr)) is not None]
   tapes[key][per]=ts
   wallets={str(f):compact(bt.wallet(ts,per,f,ms)) for f in (10,30)}
   out[key][per]={'intentions':len(xx),'unpriced':len(xx)-len(ts),'wallet':wallets,'mean_net_pct':float(100*np.mean([z['rawReturn']-.003 for z in ts])) if ts else None}
  v=[out[key][per]['wallet']['30'] for per in bt.PERIODS]
  print('BT',key,[(round(x['terminal_jpy']),round(x['max_dd_pct'],2),x['n'],round(x['win_pct'],2) if x['win_pct'] is not None else None) for x in v],flush=True)
rng=np.random.default_rng(2026112711)
for key,rs in out.items():
 arm,hh=key.split('/');hr=int(hh)
 if not(sum(v['wallet']['30']['terminal_jpy']>10000 for v in rs.values())>=2 or key in ('BOTH_MOM/24','BOTH_REV/24')):continue
 for per,rec in rs.items():
  pairs=[]
  for x in tapes[key][per]:
   side=1 if x['direction']=='LONG' else -1
   aa=[z for a in snaps[x['entryTs']] if a['symbol']!=x['symbol'] and (z:=trade(a,side,hr)) is not None]
   if len(aa)>=2:pairs.append((x,aa))
  aw=compact(bt.wallet([x for x,a in pairs],per,30,ms));ds=[compact(bt.wallet([a[rng.integers(len(a))] for x,a in pairs],per,30,ms)) for _ in range(32)];vals=[d['terminal_jpy'] for d in ds]
  rec['matched']={'n_pairs':len(pairs),'actual':aw,'mean_terminal':float(np.mean(vals)),'mean_dd':float(np.mean([d['max_dd_pct'] for d in ds])),'beats':sum(aw['terminal_jpy']>v for v in vals),'delta_pp':float(np.mean([100*(x['rawReturn']-np.mean([z['rawReturn'] for z in a])) for x,a in pairs])) if pairs else None,'draws':ds}
  print('MATCH',key,per,len(pairs),round(aw['terminal_jpy']),round(np.mean(vals)),rec['matched']['beats'],rec['matched']['delta_pp'],flush=True)
O.write_text(json.dumps({'protocol':p,'protocol_sha256':hashlib.sha256(P.read_bytes()).hexdigest(),'snapshots':len(snaps),'decomposition':D,'results':out,'intentions':{k:[{**x,'side':d} for x,d in v] for k,v in signals.items()}},indent=2,allow_nan=False),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)
